  "The app reads the names, birthdays and photos of contacts that have a birthday, so it can remind you. They stay on this phone and are never uploaded.": "Aplikasi membaca nama, ulang tahun, dan foto kontak yang punya ulang tahun, supaya bisa mengingatkanmu. Semuanya tetap di ponsel ini dan tidak pernah diunggah.",
