  "Couldn’t load the plans from the store. Check you’re signed in and online, then try again.": "Gagal memuat paket dari toko. Pastikan kamu sudah masuk dan online, lalu coba lagi.",
  "See what Premium adds": "Lihat tambahan dari Premium",
