  "All 10": "Ke-10",
  "AR fireworks and sparkler in your room": "Kembang api dan kembang api tangan AR di kamarmu",
  "Free for everyone and included with every plan.": "Gratis untuk semua dan termasuk di setiap paket.",
  "AR pictures are illustrations; the look on your phone depends on your camera and room. AR crackers on your real floor need a phone that supports Google Play Services for AR.": "Gambar AR hanya ilustrasi; tampilan di ponselmu tergantung kamera dan ruanganmu. Petasan AR di lantai sungguhan butuh ponsel yang mendukung Google Play Services for AR.",
