  "Cards you make are kept here, ready to play, change or send again.": "Kartu yang kamu buat disimpan di sini, siap diputar, diubah, atau dikirim lagi.",
  "Cards friends send you are kept here, so you can watch them again.": "Kartu dari teman disimpan di sini, jadi kamu bisa menontonnya lagi.",
  "Lit back": "Dibalas",
