  "Congratulations on your retirement! Here’s to days of rest, joy and new adventures.": "Selamat atas pensiunmu! Untuk hari-hari penuh istirahat, sukacita, dan petualangan baru.",
  "🍀 Good luck": "🍀 Semoga sukses",
