  "No reason at all. You just deserve a sky full of light.": "Tanpa alasan apa pun. Kamu memang pantas dapat langit penuh cahaya.",
  "💐 Mother’s Day": "💐 Hari Ibu",
  "Mother’s Day": "Hari Ibu",
  "Happy Mother’s Day": "Selamat Hari Ibu",
  "Thank you for your endless love and care. Happy Mother’s Day!": "Terima kasih atas cinta dan perhatianmu yang tak ada habisnya. Selamat Hari Ibu!",
  "👔 Father’s Day": "👔 Hari Ayah",
