  "Thank you for your strength, your guidance and your love. Happy Father’s Day!": "Terima kasih atas kekuatan, bimbingan, dan cintamu. Selamat Hari Ayah!",
  "🤝 Friendship Day": "🤝 Hari Persahabatan",
  "Friendship Day": "Hari Persahabatan",
