  "Thank you for teaching, guiding and believing in us. Happy Teachers’ Day!": "Terima kasih sudah mengajar, membimbing, dan percaya pada kami. Selamat Hari Guru!",
  "💘 Valentine’s Day": "💘 Hari Valentine",
  "Valentine’s Day": "Hari Valentine",
