  "Your laugh is my favourite sound": "Tawamu adalah suara favoritku",
  "I love how you make me feel safe": "Aku suka caramu membuatku merasa aman",
  "You are my calm in every storm": "Kamu ketenanganku di setiap badai",
  "I love our quiet evenings, just the two of us": "Aku suka malam-malam tenang kita, hanya berdua",
  "Planning trips with you is half the fun": "Merencanakan perjalanan bersamamu sudah separuh keseruannya",
  "I still remember the day I knew it was you": "Aku masih ingat hari aku tahu itu kamu",
  "When I felt like giving up, you never gave up on me": "Saat aku ingin menyerah, kamu tak pernah menyerah padaku",
  "Thanks for always saving me the last bite": "Terima kasih selalu menyisakan suapan terakhir untukku",
  "Thank you for choosing me, every single day": "Terima kasih sudah memilihku, setiap hari",
  "Building a life with you is my favourite adventure": "Membangun hidup bersamamu adalah petualangan favoritku",
  "Forever wouldn’t be long enough with you": "Selamanya pun tak cukup lama bersamamu",
  "You are, and always will be, my home": "Kamu adalah, dan selalu akan jadi, rumahku",
