  "Out of every sky I've seen, you're still the brightest light in mine.": "Dari semua langit yang pernah kulihat, kamu tetap cahaya paling terang di langitku.",
  "I love that home stopped being a place the day it became you.": "Aku suka rumah bukan lagi tempat sejak hari rumah itu adalah kamu.",
  "Every firework fades. What I feel for you only gets louder.": "Setiap kembang api memudar. Perasaanku padamu justru makin keras.",
  "I'd choose you on every Diwali, in every lifetime.": "Aku akan memilihmu di setiap Diwali, di setiap kehidupan.",
  "You're the reason ordinary nights feel like festivals.": "Kamu alasan malam biasa terasa seperti festival.",
  "I love you because with you, even silence feels like…": "Aku cinta kamu karena bersamamu, bahkan diam pun terasa seperti…",
  "Warning: you make my heart burst louder than a thousand-wala.": "Awas: kamu membuat hatiku meledak lebih keras dari petasan seribu renteng.",
  "Are you a sparkler? You light me up every time you smile.": "Kamu kembang api tangan ya? Kamu membuatku menyala setiap kali tersenyum.",
  "I lost my words the first time you smiled. Still looking for them.": "Aku kehilangan kata-kata saat pertama kamu tersenyum. Masih mencarinya.",
  "You, me and a rooftop full of fireworks. Say yes?": "Kamu, aku, dan atap penuh kembang api. Mau?",
  "My favourite view tonight isn't the fireworks. It's you.": "Pemandangan favoritku malam ini bukan kembang api. Tapi kamu.",
  "The first thing I noticed about you was…": "Hal pertama yang kuperhatikan darimu adalah…",
  "You make my bad days shorter and my good days shine.": "Kamu membuat hari burukku lebih singkat dan hari baikku bersinar.",
  "I love the way you laugh before you finish your own jokes.": "Aku suka caramu tertawa sebelum selesai menceritakan leluconmu sendiri.",
  "Thank you for being my safe place in a noisy world.": "Terima kasih jadi tempat amanku di dunia yang bising.",
  "Your hug is my favourite place to be.": "Pelukanmu adalah tempat favoritku.",
  "With you, every day is a little Diwali.": "Bersamamu, setiap hari adalah Diwali kecil.",
  "I love the little things you do, like…": "Aku suka hal-hal kecil yang kamu lakukan, seperti…",
  "I love you more than free gems. And that's a lot.": "Aku cinta kamu lebih dari permata gratis. Dan itu banyak.",
  "You're my favourite notification.": "Kamu notifikasi favoritku.",
  "I love you even when you steal the last laddoo.": "Aku cinta kamu bahkan saat kamu mencuri laddoo terakhir.",
  "You're the only one I'd share my phuljhari with.": "Hanya denganmu aku mau berbagi phuljhari-ku.",
  "Life with you is like a cracker: loud, bright and a little dangerous.": "Hidup bersamamu seperti petasan: keras, terang, dan sedikit berbahaya.",
  "I love you because you laugh at my worst jokes, like…": "Aku cinta kamu karena kamu tertawa mendengar lelucon terburukku, seperti…",
  "Amma, every light in my life started with you.": "Ibu, setiap cahaya dalam hidupku berawal darimu.",
  "Thank you for believing in me before I believed in myself.": "Terima kasih sudah percaya padaku sebelum aku percaya pada diriku sendiri.",
  "You gave me roots, and then you gave me wings.": "Kamu memberiku akar, lalu memberiku sayap.",
  "Friends like you make every festival feel like home.": "Teman sepertimu membuat setiap festival terasa seperti di rumah.",
  "Whatever I become, it began with your love.": "Jadi apa pun aku nanti, semuanya berawal dari cintamu.",
  "I'm grateful for you because…": "Aku bersyukur atasmu karena…",
  "Reasons to love": "Alasan untuk mencintai",
  "✨ Surprise me with a reason": "✨ Beri aku alasan kejutan",
  "Give them a reason to love you back. Pick a line, make it yours, then send it.": "Beri mereka alasan untuk membalas cintamu. Pilih kalimat, jadikan milikmu, lalu kirim.",
