  "The Silver Peacock Lamp": "Pelita Merak Perak",
  "Thieves took the temple’s silver peacock lamp. Follow the jasmine trail and bring it back": "Pencuri mengambil pelita merak perak kuil. Ikuti jejak melati dan bawa kembali",
  "Lamps for Madurai": "Pelita untuk Madurai",
  "Madurai’s temple street is full of lamps tonight, and the silver peacock lamp is the brightest.": "Jalan kuil Madurai penuh pelita malam ini, dan pelita merak perak yang paling terang.",
  "The peacock lamp is gone!": "Pelita merak hilang!",
  "Thieves have taken the silver peacock lamp and slipped into the flower market.": "Pencuri mengambil pelita merak perak dan menyelinap ke pasar bunga.",
  "Follow the jasmine": "Ikuti melatinya",
  "Light crackers to see in the dark. Follow the clues: jasmine petals, an anklet bell, a flower basket.": "Nyalakan petasan untuk melihat dalam gelap. Ikuti petunjuknya: kelopak melati, lonceng gelang kaki, keranjang bunga.",
  "Bring it back": "Bawa kembali",
  "Find the peacock lamp and carry it back to the temple steps before the lamps are lit.": "Temukan pelita merak dan bawa kembali ke tangga kuil sebelum pelita dinyalakan.",
  "🦚 The silver peacock lamp is gone! Light a cracker by the dark patch to find the jasmine trail": "🦚 Pelita merak perak hilang! Nyalakan petasan di dekat bagian gelap untuk menemukan jejak melati",
  "🚨 Seth-ji thinks YOU are the thief! Run the peacock lamp to the temple steps 🛕": "🚨 Seth-ji mengira KAMU pencurinya! Bawa lari pelita merak ke tangga kuil 🛕",
  "The peacock lamp is home!": "Pelita merak sudah pulang!",
  "The temple’s lamps shine on the silver peacock again 🪔": "Pelita kuil kembali menyinari merak perak 🪔",
  "You followed the jasmine petals, the anklet bell and the flower basket, and brought the silver peacock lamp back to the temple steps.": "Kamu mengikuti kelopak melati, lonceng gelang kaki, dan keranjang bunga, lalu membawa pelita merak perak kembali ke tangga kuil.",
  "I brought the silver peacock lamp home to the temple in Fireworks Street!": "Aku membawa pulang pelita merak perak ke kuil di Fireworks Street!",
  "Light up the jasmine trail": "Terangi jejak melati",
  "Jasmine petals! The thieves ran up the street with flowers on their feet": "Kelopak melati! Pencurinya lari ke ujung jalan dengan bunga di kaki",
  "A silver anklet bell, dropped on the run. They went this way": "Lonceng gelang kaki perak, terjatuh saat lari. Mereka lewat sini",
  "Search the flower basket": "Geledah keranjang bunga",
  "Under the jasmine in a flower-seller’s basket: the silver peacock lamp!": "Di bawah melati di keranjang penjual bunga: pelita merak perak!",
  "The Golden Deepam Lamp": "Pelita Deepam Emas",
  "Thieves took the great lamp for the Deepam. Follow the oil drips and bring it back for the lighting": "Pencuri mengambil pelita besar untuk Deepam. Ikuti tetesan minyak dan bawa kembali untuk penyalaan",
  "The great lamp": "Pelita besar",
  "Tonight the great golden lamp is to be lit for Karthigai Deepam, for the whole town to see.": "Malam ini pelita emas besar akan dinyalakan untuk Karthigai Deepam, untuk dilihat seluruh kota.",
  "The Deepam lamp is gone!": "Pelita Deepam hilang!",
  "Thieves have taken the golden lamp, still dripping with oil, into the dark streets.": "Pencuri membawa pelita emas, masih meneteskan minyak, ke jalanan gelap.",
  "Follow the oil": "Ikuti minyaknya",
  "Light crackers to see in the dark. Follow the clues: oil drips, a dropped bundle of wicks, the oil merchant’s cart.": "Nyalakan petasan untuk melihat dalam gelap. Ikuti petunjuknya: tetesan minyak, seikat sumbu yang jatuh, gerobak pedagang minyak.",
  "Light the Deepam": "Nyalakan Deepam",
  "Find the golden lamp and run it the whole street back to the temple steps.": "Temukan pelita emas dan bawa lari sepanjang jalan kembali ke tangga kuil.",
  "🪔 The golden Deepam lamp is gone! Light a cracker by the dark patch to find the oil drips": "🪔 Pelita Deepam emas hilang! Nyalakan petasan di dekat bagian gelap untuk menemukan tetesan minyak",
  "🚨 Seth-ji thinks YOU are the thief! Run the Deepam lamp to the temple steps 🛕": "🚨 Seth-ji mengira KAMU pencurinya! Bawa lari pelita Deepam ke tangga kuil 🛕",
  "The Deepam lamp is home!": "Pelita Deepam sudah pulang!",
  "The great lamp is lit and the whole street glows for Karthigai Deepam 🪔": "Pelita besar menyala dan seluruh jalan bercahaya untuk Karthigai Deepam 🪔",
  "You followed the oil drips, the wicks and the oil merchant’s cart, and brought the golden lamp back in time to light the Deepam.": "Kamu mengikuti tetesan minyak, sumbu, dan gerobak pedagang minyak, lalu membawa pelita emas kembali tepat waktu untuk menyalakan Deepam.",
  "I brought the golden Deepam lamp home for Karthigai Deepam in Fireworks Street!": "Aku membawa pulang pelita Deepam emas untuk Karthigai Deepam di Fireworks Street!",
  "Light up the oil drips": "Terangi tetesan minyak",
  "Oil drips shining in the light! The thieves went up the street": "Tetesan minyak berkilau terkena cahaya! Pencurinya lari ke ujung jalan",
  "A bundle of cotton wicks, dropped in a hurry. They went this way": "Seikat sumbu kapas, terjatuh karena terburu-buru. Mereka lewat sini",
  "Search the oil merchant’s cart": "Geledah gerobak pedagang minyak",
  "Behind the oil tins in the merchant’s cart: the golden Deepam lamp!": "Di balik kaleng minyak di gerobak pedagang: pelita Deepam emas!",
  "Seth-ji grabbed it! Keep running?": "Seth-ji merebutnya! Terus lari?",
  "Hold on to it and run for the temple steps, or let it fall at your feet.": "Pegang erat dan lari ke tangga kuil, atau biarkan jatuh di kakimu.",
  "Keep it (Premium)": "Pegang (Premium)",
