  "Birthdays are read from your contacts on this phone only. Nothing is uploaded.": "Ulang tahun dibaca dari kontak di ponsel ini saja. Tidak ada yang diunggah.",
  "Next, your phone asks to let the app read your contacts and, if you like, your calendar: only the names, birthdays and photos of people with a birthday, and the birthdays in your Google Birthdays calendar. You pick who to add, and they stay on this phone. Not now keeps everything else working.": "Berikutnya, ponselmu meminta izin agar aplikasi bisa membaca kontakmu dan, jika mau, kalendermu: hanya nama, ulang tahun, dan foto orang yang punya ulang tahun, serta ulang tahun di kalender Google Birthdays-mu. Kamu memilih siapa yang ditambahkan, dan semuanya tetap di ponsel ini. Jangan sekarang membuat fitur lain tetap berjalan.",
  "Remind me on their birthday": "Ingatkan aku di hari ulang tahun mereka",
  "Allow notifications and the app reminds you the day before and on the morning of each birthday. The reminders are made on this phone; nothing is sent anywhere.": "Izinkan notifikasi dan aplikasi akan mengingatkanmu sehari sebelumnya dan di pagi hari setiap ulang tahun. Pengingat dibuat di ponsel ini; tidak ada yang dikirim ke mana pun.",
