  "May this Vishu fill your year with light, plenty and golden konna flowers.": "Semoga Vishu ini memenuhi tahunmu dengan cahaya, kelimpahan, dan bunga konna keemasan.",
  "May good always win over evil in your life. Happy Dussehra!": "Semoga kebaikan selalu menang atas kejahatan dalam hidupmu. Selamat Dussehra!",
